import { PrismaClient } from '@prisma/client';
import { activitiesData } from './src/lib/data/activities-data';
import { generateShortId, ShortIdPrefix } from './src/lib/id-generator';

const prisma = new PrismaClient();

async function main() {
    console.log("Starting Static Activities Seed...");

    const allActivities = Object.values(activitiesData).flat();
    console.log(`Found ${allActivities.length} static activities.`);

    for (const activity of allActivities) {
        if (!activity.id) {
            console.warn("Skipping activity without ID:", activity.title);
            continue;
        }

        const existing = await prisma.service.findUnique({
            where: { id: activity.id }
        });

        if (existing) {
            console.log(`Activity ${activity.id} already exists.`);
            // Optional: Update it? For now, we assume static data is source of truth if we want to sync.
            // Let's UPDATE it to ensure DB matches code.
            await prisma.service.update({
                where: { id: activity.id },
                data: {
                    title: activity.title,
                    description: activity.description,
                    price: activity.price,
                    category: activity.category,
                    rating: activity.rating,
                    reviews: activity.reviews,
                    duration: activity.duration,
                    location: activity.location,
                    images: activity.images || (activity.image ? [activity.image] : []),
                    features: activity.features,
                    included: activity.included,
                    whatToBring: activity.whatToBring,
                    tags: activity.tags,
                    // Handle complex objects as JSON
                    host: activity.host ? JSON.stringify(activity.host) : "Unknown",
                    itinerary: activity.itinerary ? JSON.stringify(activity.itinerary) : undefined,
                    // Extra fields stored in JSON or mapped if schema supports
                    // Schema doesn't have specific fields for 'programs' etc, so we might lose some data if not mapped effectively.
                    // But standard fields are covered.

                    // IMPORTANT: Ensure shortId exists
                    shortId: (existing as any).shortId || generateShortId(ShortIdPrefix.SERVICE),
                } as any
            });
            console.log(`Updated ${activity.id}`);
        } else {
            console.log(`Creating ${activity.id}...`);
            await prisma.service.create({
                data: {
                    id: activity.id, // KEEP the static ID
                    title: activity.title,
                    description: activity.description,
                    price: activity.price,
                    category: activity.category,
                    rating: activity.rating,
                    reviews: activity.reviews,
                    duration: activity.duration,
                    location: activity.location,
                    images: activity.images || (activity.image ? [activity.image] : []),
                    features: activity.features,
                    included: activity.included,
                    whatToBring: activity.whatToBring,
                    tags: activity.tags,
                    host: activity.host ? JSON.stringify(activity.host) : "Unknown",
                    itinerary: activity.itinerary ? JSON.stringify(activity.itinerary) : undefined,

                    shortId: generateShortId(ShortIdPrefix.SERVICE),
                } as any
            });
        }
    }

    console.log("Seeding complete.");
}

main()
    .catch((e) => {
        console.error(e);
        process.exit(1);
    })
    .finally(async () => {
        await prisma.$disconnect();
    });

'use server'

import prisma from '@/lib/prisma'
import { revalidatePath } from 'next/cache'

export async function getBookings() {
    try {
        const bookings = await prisma.booking.findMany({
            orderBy: {
                date: 'desc',
            },
        })
        return { success: true, data: bookings }
    } catch (error) {
        console.error('Failed to fetch bookings:', error)
        return { success: false, error: 'Failed to fetch bookings' }
    }
}

export async function updateBookingStatus(id: string, status: string) {
    try {
        await prisma.booking.update({
            where: { id },
            data: { status: status as any },
        })
        revalidatePath('/admin/bookings')
        revalidatePath('/admin/dashboard')
        return { success: true }
    } catch (error) {
        console.error('Failed to update booking status:', error)
        throw new Error('Failed to update booking status')
    }
}

export async function confirmBooking(id: string) {
    try {
        const booking = await prisma.booking.findUnique({
            where: { id },
            include: { user: true }
        });

        if (!booking) {
            return { success: false, error: 'Booking not found' };
        }

        await prisma.booking.update({
            where: { id },
            data: { status: 'CONFIRMED' },
        });

        // Send confirmation email
        try {
            const { emailService } = await import('@/services/email.service');
            await emailService.sendBookingConfirmation(
                booking.email,
                booking.name,
                booking.id,
                booking.activityTitle,
                booking.date,
                booking.guests,
                booking.totalPrice
            );
        } catch (error) {
            console.error('Failed to send confirmation email:', error);
        }

        revalidatePath('/admin/bookings');
        revalidatePath('/admin/dashboard');
        return { success: true };
    } catch (error) {
        console.error('Failed to confirm booking:', error);
        return { success: false, error: 'Failed to confirm booking' };
    }
}

export async function cancelBooking(id: string) {
    try {
        const booking = await prisma.booking.findUnique({
            where: { id }
        });

        if (!booking) {
            return { success: false, error: 'Booking not found' };
        }

        await prisma.booking.update({
            where: { id },
            data: { status: 'CANCELLED' },
        });

        // Send cancellation email
        try {
            const { emailService } = await import('@/services/email.service');
            await emailService.sendBookingCancellation(
                booking.email,
                booking.name,
                booking.activityTitle,
                booking.paymentStatus === 'PAID' ? booking.totalPrice : undefined
            );
        } catch (error) {
            console.error('Failed to send cancellation email:', error);
        }

        revalidatePath('/admin/bookings');
        revalidatePath('/admin/dashboard');
        return { success: true };
    } catch (error) {
        console.error('Failed to cancel booking:', error);
        return { success: false, error: 'Failed to cancel booking' };
    }
}

export async function processBooking(id: string) {
    try {
        await prisma.booking.update({
            where: { id },
            data: { status: 'COMPLETED' },
        })
        revalidatePath('/admin/bookings')
        revalidatePath('/admin/dashboard')
        return { success: true }
    } catch (error) {
        console.error('Failed to process booking:', error)
        return { success: false, error: 'Failed to process booking' }
    }
}

export async function deleteBooking(id: string) {
    try {
        await prisma.booking.delete({
            where: { id },
        })
        revalidatePath('/admin/bookings')
        return { success: true }
    } catch (error) {
        console.error('Failed to delete booking:', error)
        return { success: false, error: 'Failed to delete booking' }
    }
}

'use client';

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Button } from '@/components/ui/button';
import { Download, TrendingUp, TrendingDown, DollarSign, Calendar, Users } from 'lucide-react';
import { format, subDays, startOfDay, endOfDay } from 'date-fns';
import { toast } from 'sonner';

interface AnalyticsData {
    revenue: {
        today: number;
        week: number;
        month: number;
        total: number;
        change: number;
    };
    bookings: {
        today: number;
        week: number;
        month: number;
        total: number;
        change: number;
    };
    users: {
        total: number;
        newThisWeek: number;
        change: number;
    };
    topServices: Array<{
        id: string;
        title: string;
        bookings: number;
        revenue: number;
    }>;
    recentTrends: Array<{
        date: string;
        bookings: number;
        revenue: number;
    }>;
}

export default function AnalyticsPage() {
    const [data, setData] = useState<AnalyticsData | null>(null);
    const [loading, setLoading] = useState(true);
    const [dateRange, setDateRange] = useState<'7d' | '30d' | '90d'>('30d');

    useEffect(() => {
        fetchAnalytics();
    }, [dateRange]);

    const fetchAnalytics = async () => {
        try {
            setLoading(true);
            const res = await fetch(`/api/admin/analytics?range=${dateRange}`);
            
            if (!res.ok) {
                const errorData = await res.json().catch(() => ({}));
                const errorMessage = errorData?.error?.message || `HTTP ${res.status}: Failed to fetch analytics`;
                console.error('Analytics API error:', errorMessage, errorData);
                toast.error(`Failed to load analytics: ${errorMessage}`);
                // Set empty data structure to show error state
                setData({
                    revenue: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                    bookings: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                    users: { total: 0, newThisWeek: 0, change: 0 },
                    topServices: [],
                    recentTrends: []
                });
                return;
            }
            
            const analyticsData = await res.json();
            // Handle both wrapped and unwrapped responses
            const data = analyticsData.data || analyticsData;
            
            // Validate data structure
            if (!data || typeof data !== 'object') {
                throw new Error('Invalid analytics data format');
            }
            
            setData(data);
        } catch (error) {
            console.error('Error fetching analytics:', error);
            const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';
            toast.error(`Failed to load analytics: ${errorMessage}`);
            // Set empty data structure to show error state
            setData({
                revenue: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                bookings: { today: 0, week: 0, month: 0, total: 0, change: 0 },
                users: { total: 0, newThisWeek: 0, change: 0 },
                topServices: [],
                recentTrends: []
            });
        } finally {
            setLoading(false);
        }
    };

    const exportBookings = async () => {
        try {
            const res = await fetch('/api/admin/bookings/export');
            if (!res.ok) throw new Error('Failed to export');
            const blob = await res.blob();
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `bookings-${format(new Date(), 'yyyy-MM-dd')}.csv`;
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);
        } catch (error) {
            console.error('Export error:', error);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading analytics...</p>
                </div>
            </div>
        );
    }

    if (!data) {
        return <div>No data available</div>;
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Analytics Dashboard</h1>
                    <p className="text-muted-foreground">Comprehensive insights into your platform performance</p>
                </div>
                <Button onClick={exportBookings}>
                    <Download className="w-4 h-4 mr-2" />
                    Export Bookings
                </Button>
            </div>

            <Tabs value={dateRange} onValueChange={(v) => setDateRange(v as '7d' | '30d' | '90d')}>
                <TabsList>
                    <TabsTrigger value="7d">Last 7 Days</TabsTrigger>
                    <TabsTrigger value="30d">Last 30 Days</TabsTrigger>
                    <TabsTrigger value="90d">Last 90 Days</TabsTrigger>
                </TabsList>
            </Tabs>

            {/* Key Metrics */}
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Revenue</CardTitle>
                        <DollarSign className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">Γé¼{data.revenue.total.toLocaleString()}</div>
                        <div className="flex items-center text-xs text-muted-foreground mt-1">
                            {data.revenue.change >= 0 ? (
                                <TrendingUp className="h-3 w-3 mr-1 text-green-500" />
                            ) : (
                                <TrendingDown className="h-3 w-3 mr-1 text-red-500" />
                            )}
                            <span className={data.revenue.change >= 0 ? 'text-green-500' : 'text-red-500'}>
                                {Math.abs(data.revenue.change).toFixed(1)}%
                            </span>
                            <span className="ml-1">vs previous period</span>
                        </div>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Bookings</CardTitle>
                        <Calendar className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{data.bookings.total}</div>
                        <div className="flex items-center text-xs text-muted-foreground mt-1">
                            {data.bookings.change >= 0 ? (
                                <TrendingUp className="h-3 w-3 mr-1 text-green-500" />
                            ) : (
                                <TrendingDown className="h-3 w-3 mr-1 text-red-500" />
                            )}
                            <span className={data.bookings.change >= 0 ? 'text-green-500' : 'text-red-500'}>
                                {Math.abs(data.bookings.change).toFixed(1)}%
                            </span>
                            <span className="ml-1">vs previous period</span>
                        </div>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Users</CardTitle>
                        <Users className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{data.users.total}</div>
                        <p className="text-xs text-muted-foreground mt-1">
                            {data.users.newThisWeek} new this week
                        </p>
                    </CardContent>
                </Card>

                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Avg. Booking Value</CardTitle>
                        <DollarSign className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">
                            Γé¼{data.bookings.total > 0 
                                ? (data.revenue.total / data.bookings.total).toFixed(2)
                                : '0.00'
                            }
                        </div>
                        <p className="text-xs text-muted-foreground mt-1">
                            Per booking
                        </p>
                    </CardContent>
                </Card>
            </div>

            {/* Top Services */}
            <Card>
                <CardHeader>
                    <CardTitle>Top Performing Services</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="space-y-4">
                        {data.topServices.length > 0 ? (
                            data.topServices.map((service, index) => (
                                <div key={service.id} className="flex items-center justify-between border-b pb-4 last:border-0 last:pb-0">
                                    <div className="flex items-center gap-4">
                                        <div className="w-8 h-8 rounded-full bg-[#FF5F00]/10 flex items-center justify-center font-bold text-[#FF5F00]">
                                            {index + 1}
                                        </div>
                                        <div>
                                            <p className="font-medium">{service.title}</p>
                                            <p className="text-sm text-muted-foreground">
                                                {service.bookings} bookings
                                            </p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="font-bold">Γé¼{service.revenue.toFixed(2)}</p>
                                        <p className="text-xs text-muted-foreground">Revenue</p>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <p className="text-sm text-muted-foreground">No data available</p>
                        )}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from "@/components/ui/select";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Mail, Phone, Calendar, Trash2, RefreshCw } from "lucide-react";
import { toast } from "sonner";
import { format } from "date-fns";

interface SupportRequest {
    id: string;
    name: string;
    email: string;
    phone: string | null;
    subject: string;
    message: string;
    status: string;
    createdAt: string;
    updatedAt: string;
}

export default function ComplaintsPage() {
    const [requests, setRequests] = useState<SupportRequest[]>([]);
    const [loading, setLoading] = useState(true);
    const [statusFilter, setStatusFilter] = useState("ALL");
    const [deleteId, setDeleteId] = useState<string | null>(null);

    const fetchRequests = async () => {
        try {
            setLoading(true);
            const url = statusFilter === "ALL"
                ? "/api/admin/support-requests"
                : `/api/admin/support-requests?status=${statusFilter}`;

            const response = await fetch(url);
            if (!response.ok) throw new Error("Failed to fetch");

            const data = await response.json();
            setRequests(data);
        } catch (error) {
            toast.error("Failed to load support requests");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchRequests();
    }, [statusFilter]);

    const updateStatus = async (id: string, newStatus: string) => {
        try {
            const response = await fetch(`/api/admin/support-requests/${id}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ status: newStatus }),
            });

            if (!response.ok) throw new Error("Failed to update");

            toast.success("Status updated successfully");
            fetchRequests();
        } catch (error) {
            toast.error("Failed to update status");
        }
    };

    const deleteRequest = async (id: string) => {
        try {
            const response = await fetch(`/api/admin/support-requests/${id}`, {
                method: "DELETE",
            });

            if (!response.ok) throw new Error("Failed to delete");

            toast.success("Request deleted successfully");
            setDeleteId(null);
            fetchRequests();
        } catch (error) {
            toast.error("Failed to delete request");
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case "PENDING":
                return "bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400";
            case "IN_PROGRESS":
                return "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400";
            case "RESOLVED":
                return "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400";
            default:
                return "bg-gray-100 text-gray-800 dark:bg-gray-900/30 dark:text-gray-400";
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Support Requests</h1>
                    <p className="text-muted-foreground mt-1">
                        Manage customer support requests and complaints
                    </p>
                </div>
                <div className="flex items-center gap-3">
                    <Select value={statusFilter} onValueChange={setStatusFilter}>
                        <SelectTrigger className="w-[180px]">
                            <SelectValue placeholder="Filter by status" />
                        </SelectTrigger>
                        <SelectContent>
                            <SelectItem value="ALL">All Requests</SelectItem>
                            <SelectItem value="PENDING">Pending</SelectItem>
                            <SelectItem value="IN_PROGRESS">In Progress</SelectItem>
                            <SelectItem value="RESOLVED">Resolved</SelectItem>
                        </SelectContent>
                    </Select>
                    <Button onClick={fetchRequests} variant="outline" size="icon">
                        <RefreshCw className="h-4 w-4" />
                    </Button>
                </div>
            </div>

            {loading ? (
                <div className="flex justify-center items-center py-12">
                    <RefreshCw className="h-8 w-8 animate-spin text-primary" />
                </div>
            ) : requests.length === 0 ? (
                <Card>
                    <CardContent className="py-12 text-center">
                        <p className="text-muted-foreground">No support requests found</p>
                    </CardContent>
                </Card>
            ) : (
                <div className="grid gap-6">
                    {requests.map((request) => (
                        <Card key={request.id} className="hover:shadow-md transition-shadow">
                            <CardHeader className="pb-3">
                                <div className="flex flex-col sm:flex-row justify-between items-start gap-3">
                                    <div className="flex-1">
                                        <CardTitle className="text-xl mb-2">{request.subject}</CardTitle>
                                        <div className="flex flex-wrap items-center gap-3 text-sm text-muted-foreground">
                                            <div className="flex items-center gap-1.5">
                                                <Mail className="h-4 w-4" />
                                                <span>{request.email}</span>
                                            </div>
                                            {request.phone && (
                                                <div className="flex items-center gap-1.5">
                                                    <Phone className="h-4 w-4" />
                                                    <span>{request.phone}</span>
                                                </div>
                                            )}
                                            <div className="flex items-center gap-1.5">
                                                <Calendar className="h-4 w-4" />
                                                <span>{format(new Date(request.createdAt), "MMM dd, yyyy")}</span>
                                            </div>
                                        </div>
                                    </div>
                                    <Badge className={getStatusColor(request.status)}>
                                        {request.status.replace("_", " ")}
                                    </Badge>
                                </div>
                            </CardHeader>
                            <CardContent className="space-y-4">
                                <div>
                                    <p className="text-sm font-medium mb-1">From: {request.name}</p>
                                    <p className="text-sm text-muted-foreground whitespace-pre-wrap">
                                        {request.message}
                                    </p>
                                </div>
                                <div className="flex flex-wrap gap-2 pt-2 border-t">
                                    <Select
                                        value={request.status}
                                        onValueChange={(value) => updateStatus(request.id, value)}
                                    >
                                        <SelectTrigger className="w-[160px]">
                                            <SelectValue />
                                        </SelectTrigger>
                                        <SelectContent>
                                            <SelectItem value="PENDING">Pending</SelectItem>
                                            <SelectItem value="IN_PROGRESS">In Progress</SelectItem>
                                            <SelectItem value="RESOLVED">Resolved</SelectItem>
                                        </SelectContent>
                                    </Select>
                                    <Button
                                        variant="destructive"
                                        size="sm"
                                        onClick={() => setDeleteId(request.id)}
                                    >
                                        <Trash2 className="h-4 w-4 mr-2" />
                                        Delete
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    ))}
                </div>
            )}

            <AlertDialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
                <AlertDialogContent>
                    <AlertDialogHeader>
                        <AlertDialogTitle>Are you sure?</AlertDialogTitle>
                        <AlertDialogDescription>
                            This action cannot be undone. This will permanently delete the support request.
                        </AlertDialogDescription>
                    </AlertDialogHeader>
                    <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                            onClick={() => deleteId && deleteRequest(deleteId)}
                            className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                        >
                            Delete
                        </AlertDialogAction>
                    </AlertDialogFooter>
                </AlertDialogContent>
            </AlertDialog>
        </div>
    );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { CalendarDays, CreditCard, TrendingUp, Users } from "lucide-react";
import Link from "next/link";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import { adminService } from "@/services/admin.service";

export const dynamic = 'force-dynamic';

async function getData() {
    // Fetch stats concurrently
    const stats = await adminService.getDashboardStats();

    return {
        stats: {
            bookingsCount: stats.overview.totalBookings,
            usersCount: stats.users.total,
            servicesCount: stats.overview.totalServices,
            totalRevenue: stats.revenue.total
        },
        recentBookings: stats.recent.bookings
    };
}

