import { NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/authorization';
import { errorResponse, successResponse } from '@/lib/api-response';
import prisma from '@/lib/prisma';
import { subDays, startOfDay, endOfDay } from 'date-fns';

export async function GET(request: Request) {
    try {
        await requireAdmin();

        const { searchParams } = new URL(request.url);
        const range = searchParams.get('range') || '30d';
        
        const days = range === '7d' ? 7 : range === '90d' ? 90 : 30;
        const startDate = startOfDay(subDays(new Date(), days));
        const previousStartDate = startOfDay(subDays(startDate, days));
        const previousEndDate = endOfDay(subDays(startDate, 1));

        // Revenue calculations
        const revenueThisPeriod = await prisma.booking.aggregate({
            where: {
                date: { gte: startDate },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenuePreviousPeriod = await prisma.booking.aggregate({
            where: {
                date: { gte: previousStartDate, lte: previousEndDate },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenueToday = await prisma.booking.aggregate({
            where: {
                date: { gte: startOfDay(new Date()), lte: endOfDay(new Date()) },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenueWeek = await prisma.booking.aggregate({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 7)) },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const revenueMonth = await prisma.booking.aggregate({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 30)) },
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        const totalRevenue = await prisma.booking.aggregate({
            where: {
                status: { not: 'CANCELLED' }
            },
            _sum: { totalPrice: true }
        });

        // Bookings calculations
        const bookingsThisPeriod = await prisma.booking.count({
            where: {
                date: { gte: startDate },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsPreviousPeriod = await prisma.booking.count({
            where: {
                date: { gte: previousStartDate, lte: previousEndDate },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsToday = await prisma.booking.count({
            where: {
                date: { gte: startOfDay(new Date()), lte: endOfDay(new Date()) },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsWeek = await prisma.booking.count({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 7)) },
                status: { not: 'CANCELLED' }
            }
        });

        const bookingsMonth = await prisma.booking.count({
            where: {
                date: { gte: startOfDay(subDays(new Date(), 30)) },
                status: { not: 'CANCELLED' }
            }
        });

        const totalBookings = await prisma.booking.count({
            where: {
                status: { not: 'CANCELLED' }
            }
        });

        // Users
        const totalUsers = await prisma.user.count();
        const newUsersThisWeek = await prisma.user.count({
            where: {
                createdAt: { gte: startOfDay(subDays(new Date(), 7)) }
            }
        });

        // Top services
        const topServicesData = await prisma.booking.groupBy({
            by: ['activityId', 'activityTitle'],
            where: {
                date: { gte: startDate },
                status: { not: 'CANCELLED' }
            },
            _count: { id: true },
            _sum: { totalPrice: true },
            orderBy: { _sum: { totalPrice: 'desc' } },
            take: 5
        });

        const topServices = await Promise.all(
            topServicesData
                .filter(item => item.activityId) // Filter out null activityIds
                .map(async (item) => {
                    let serviceTitle = item.activityTitle;
                    if (item.activityId) {
                        try {
                            const service = await prisma.service.findUnique({
                                where: { id: item.activityId },
                                select: { title: true }
                            });
                            if (service?.title) {
                                serviceTitle = service.title;
                            }
                        } catch (error) {
                            // If service not found, use activityTitle from booking
                            console.warn(`Service ${item.activityId} not found, using activityTitle`);
                        }
                    }
                    return {
                        id: item.activityId || 'unknown',
                        title: serviceTitle || 'Unknown Service',
                        bookings: item._count.id,
                        revenue: item._sum.totalPrice || 0
                    };
                })
        );

        // Calculate percentage changes
        const revenueChange = revenuePreviousPeriod._sum.totalPrice 
            ? ((revenueThisPeriod._sum.totalPrice || 0) - (revenuePreviousPeriod._sum.totalPrice || 0)) / (revenuePreviousPeriod._sum.totalPrice || 1) * 100
            : 0;

        const bookingsChange = bookingsPreviousPeriod
            ? ((bookingsThisPeriod - bookingsPreviousPeriod) / bookingsPreviousPeriod) * 100
            : 0;

        const analytics = {
            revenue: {
                today: revenueToday._sum.totalPrice || 0,
                week: revenueWeek._sum.totalPrice || 0,
                month: revenueMonth._sum.totalPrice || 0,
                total: totalRevenue._sum.totalPrice || 0,
                change: revenueChange
            },
            bookings: {
                today: bookingsToday,
                week: bookingsWeek,
                month: bookingsMonth,
                total: totalBookings,
                change: bookingsChange
            },
            users: {
                total: totalUsers,
                newThisWeek: newUsersThisWeek,
                change: 0 // Can be calculated if needed
            },
            topServices,
            recentTrends: [] // Can be enhanced with daily breakdown
        };

        return successResponse(analytics);
    } catch (error) {
        return errorResponse(error);
    }
}

import { NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/authorization';
import { errorResponse, successResponse } from '@/lib/api-response';
import prisma from '@/lib/prisma';
import { format } from 'date-fns';

/**
 * GET: Export bookings as CSV
 */
export async function GET(request: Request) {
    try {
        await requireAdmin();

        const { searchParams } = new URL(request.url);
        const status = searchParams.get('status');
        const startDate = searchParams.get('startDate');
        const endDate = searchParams.get('endDate');

        // Build where clause
        const where: any = {};
        if (status && status !== 'ALL') {
            where.status = status;
        }
        if (startDate || endDate) {
            where.date = {};
            if (startDate) {
                where.date.gte = new Date(startDate);
            }
            if (endDate) {
                where.date.lte = new Date(endDate);
            }
        }

        // Fetch bookings
        const bookings = await prisma.booking.findMany({
            where,
            orderBy: { createdAt: 'desc' },
            include: {
                user: {
                    select: {
                        name: true,
                        email: true
                    }
                }
            }
        });

        // Convert to CSV
        const headers = [
            'Booking ID',
            'Short ID',
            'Customer Name',
            'Email',
            'Phone',
            'Activity Title',
            'Date',
            'Time',
            'Guests',
            'Total Price',
            'Status',
            'Payment Status',
            'Created At'
        ];

        const rows = bookings.map(booking => [
            booking.id,
            (booking as any).shortId || '',
            booking.user?.name || booking.name,
            booking.user?.email || booking.email,
            booking.phone || '',
            booking.activityTitle,
            format(new Date(booking.date), 'yyyy-MM-dd'),
            format(new Date(booking.date), 'HH:mm'),
            booking.guests.toString(),
            booking.totalPrice.toFixed(2),
            booking.status,
            booking.paymentStatus,
            format(new Date(booking.createdAt), 'yyyy-MM-dd HH:mm:ss')
        ]);

        const csv = [
            headers.join(','),
            ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(','))
        ].join('\n');

        // Return CSV file
        return new NextResponse(csv, {
            headers: {
                'Content-Type': 'text/csv',
                'Content-Disposition': `attachment; filename="bookings-${format(new Date(), 'yyyy-MM-dd')}.csv"`
            }
        });

    } catch (error) {
        return errorResponse(error);
    }
}

import { NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/authorization';
import { errorResponse, successResponse } from '@/lib/api-response';
import prisma from '@/lib/prisma';
import { emailService } from '@/services/email.service';
import { addHours, startOfDay, endOfDay } from 'date-fns';

/**
 * POST: Send booking reminders for bookings happening in 24 hours
 * This can be called by a cron job or scheduled task
 */
export async function POST(request: Request) {
    try {
        await requireAdmin();

        // Find bookings happening in the next 24-25 hours (to catch all bookings for tomorrow)
        const tomorrow = addHours(new Date(), 24);
        const tomorrowEnd = addHours(new Date(), 25);

        const upcomingBookings = await prisma.booking.findMany({
            where: {
                date: {
                    gte: startOfDay(tomorrow),
                    lte: endOfDay(tomorrowEnd)
                },
                status: {
                    in: ['CONFIRMED', 'PENDING']
                },
                // Only send to bookings that haven't received a reminder yet
                // You might want to add a 'reminderSent' field to track this
            },
            include: {
                user: {
                    select: {
                        name: true,
                        email: true
                    }
                }
            }
        });

        let sentCount = 0;
        let failedCount = 0;

        for (const booking of upcomingBookings) {
            try {
                await emailService.sendBookingReminder(
                    booking.user?.email || booking.email,
                    booking.user?.name || booking.name,
                    booking.activityTitle,
                    booking.date,
                    booking.guests
                );
                sentCount++;
            } catch (error) {
                console.error(`Failed to send reminder for booking ${booking.id}:`, error);
                failedCount++;
            }
        }

        return successResponse({
            total: upcomingBookings.length,
            sent: sentCount,
            failed: failedCount,
            message: `Sent ${sentCount} reminders, ${failedCount} failed`
        });
    } catch (error) {
        return errorResponse(error);
    }
}

