                                <div className="flex-1">
                                    <h3 className="font-semibold text-gray-900">View All Bookings</h3>
                                    <p className="text-sm text-gray-600">
                                        Manage your past and upcoming trips
                                    </p>
                                </div>
                                <ArrowRight className="w-5 h-5 text-gray-400" />
