"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { CreditCard, Download, AlertCircle } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";

interface Payment {
    id: string;
    amount: number;
    currency: string;
    status: string;
    method?: string;
    createdAt: string;
    booking: {
        id: string;
        activityTitle: string;
    };
}

export default function PaymentsPage() {
    const [payments, setPayments] = useState<Payment[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState("all");

    useEffect(() => {
        fetchPayments();
    }, []);

    const fetchPayments = async () => {
        try {
            // Fetch bookings with payment information
            const res = await fetch("/api/bookings");
            if (!res.ok) throw new Error("Failed to fetch payments");
            const data = await res.json();
            // Handle wrapped response
            const bookings = data.data || data;

            // Extract payments from bookings
            const paymentsData: Payment[] = [];
            bookings.forEach((booking: any) => {
                if (booking.payments && booking.payments.length > 0) {
                    booking.payments.forEach((payment: any) => {
                        paymentsData.push({
                            ...payment,
                            booking: {
                                id: booking.id,
                                activityTitle: booking.activityTitle,
                            },
                        });
                    });
                } else if (booking.paymentStatus === "PAID") {
                    // Create a virtual payment record for bookings marked as paid
                    paymentsData.push({
                        id: `virtual-${booking.id}`,
                        amount: booking.totalPrice,
                        currency: "EUR",
                        status: "COMPLETED",
                        method: "UNKNOWN",
                        createdAt: booking.createdAt,
                        booking: {
                            id: booking.id,
                            activityTitle: booking.activityTitle,
                        },
                    });
                }
            });

            setPayments(paymentsData);
        } catch (error) {
            console.error("Error fetching payments:", error);
            toast.error("Failed to load payment history");
        } finally {
            setLoading(false);
        }
    };

    const filterPayments = (filter: string) => {
        switch (filter) {
            case "completed":
                return payments.filter((p) => p.status === "COMPLETED");
            case "pending":
                return payments.filter((p) => p.status === "PENDING");
            case "failed":
                return payments.filter((p) => p.status === "FAILED");
            default:
                return payments;
        }
    };

    const getStatusColor = (status: string) => {
        switch (status) {
            case "COMPLETED":
                return "bg-green-100 text-green-800";
            case "PENDING":
                return "bg-yellow-100 text-yellow-800";
            case "FAILED":
                return "bg-red-100 text-red-800";
            default:
                return "bg-gray-100 text-gray-800";
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading payment history...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-3xl font-bold text-gray-900">Payment History</h1>
                <p className="text-gray-600 mt-1">
                    View your transaction history and invoices
                </p>
            </div>

            <Tabs value={activeTab} onValueChange={setActiveTab}>
                <TabsList>
                    <TabsTrigger value="all">All ({payments.length})</TabsTrigger>
                    <TabsTrigger value="completed">
                        Completed ({payments.filter((p) => p.status === "COMPLETED").length})
                    </TabsTrigger>
                    <TabsTrigger value="pending">
                        Pending ({payments.filter((p) => p.status === "PENDING").length})
                    </TabsTrigger>
                    <TabsTrigger value="failed">
                        Failed ({payments.filter((p) => p.status === "FAILED").length})
                    </TabsTrigger>
                </TabsList>

                <TabsContent value={activeTab} className="mt-6">
                    {filterPayments(activeTab).length > 0 ? (
                        <Card>
                            <CardContent className="p-0">
                                <Table>
                                    <TableHeader>
                                        <TableRow>
                                            <TableHead>Date</TableHead>
                                            <TableHead>Booking</TableHead>
                                            <TableHead>Amount</TableHead>
                                            <TableHead>Method</TableHead>
                                            <TableHead>Status</TableHead>
                                            <TableHead className="text-right">Actions</TableHead>
                                        </TableRow>
                                    </TableHeader>
                                    <TableBody>
                                        {filterPayments(activeTab).map((payment) => (
                                            <TableRow key={payment.id}>
                                                <TableCell>
                                                    {new Date(payment.createdAt).toLocaleDateString(
                                                        "en-US",
                                                        {
                                                            year: "numeric",
                                                            month: "short",
                                                            day: "numeric",
                                                        }
                                                    )}
                                                </TableCell>
                                                <TableCell>
                                                    <Link
                                                        href={`/client/bookings/${payment.booking.id}`}
                                                        className="text-[#FF5F00] hover:underline"
                                                    >
                                                        {payment.booking.activityTitle}
                                                    </Link>
                                                </TableCell>
                                                <TableCell className="font-medium">
                                                    Γé¼{payment.amount.toFixed(2)}
                                                </TableCell>
                                                <TableCell className="capitalize">
                                                    {payment.method?.toLowerCase() || "N/A"}
                                                </TableCell>
                                                <TableCell>
                                                    <span
                                                        className={`inline-block px-2 py-1 text-xs font-medium rounded ${getStatusColor(
                                                            payment.status
                                                        )}`}
                                                    >
                                                        {payment.status}
                                                    </span>
                                                </TableCell>
                                                <TableCell className="text-right">
                                                    {payment.status === "COMPLETED" && (
                                                        <Button variant="ghost" size="sm">
                                                            <Download className="w-4 h-4 mr-2" />
                                                            Invoice
                                                        </Button>
                                                    )}
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                    </TableBody>
                                </Table>
                            </CardContent>
                        </Card>
                    ) : (
                        <Card>
                            <CardContent className="py-12 text-center">
                                <AlertCircle className="w-12 h-12 text-gray-400 mx-auto mb-4" />
                                <h3 className="text-lg font-semibold text-gray-900 mb-2">
                                    No {activeTab} payments
                                </h3>
                                <p className="text-gray-600">
                                    {activeTab === "all"
                                        ? "You haven't made any payments yet"
                                        : `No ${activeTab} payments to show`}
                                </p>
                            </CardContent>
                        </Card>
                    )}
                </TabsContent>
            </Tabs>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { User, Mail, Phone, Save, Lock } from "lucide-react";
import { toast } from "sonner";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";

interface UserProfile {
    id: string;
    name: string;
    email: string;
    phone?: string;
}

export default function ProfilePage() {
    const [profile, setProfile] = useState<UserProfile | null>(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        phone: "",
    });
    const [passwordData, setPasswordData] = useState({
        currentPassword: "",
        newPassword: "",
        confirmPassword: "",
    });
    const [changingPassword, setChangingPassword] = useState(false);
    const [dialogOpen, setDialogOpen] = useState(false);

    useEffect(() => {
        fetchProfile();
    }, []);

    const fetchProfile = async () => {
        try {
            const res = await fetch("/api/user");
            if (!res.ok) throw new Error("Failed to fetch profile");
            const data = await res.json();
            // User API returns direct data, not wrapped
            setProfile(data);
            setFormData({
                name: data.name || "",
                phone: data.phone || "",
            });
        } catch (error) {
            console.error("Error fetching profile:", error);
            toast.error("Failed to load profile");
        } finally {
            setLoading(false);
        }
    };

    const handleSaveProfile = async (e: React.FormEvent) => {
        e.preventDefault();
        setSaving(true);
        try {
            const res = await fetch("/api/user", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(formData),
            });

            if (!res.ok) throw new Error("Failed to update profile");

            toast.success("Profile updated successfully");
            await fetchProfile();
        } catch (error) {
            console.error("Error updating profile:", error);
            toast.error("Failed to update profile");
        } finally {
            setSaving(false);
        }
    };

    const handleChangePassword = async (e: React.FormEvent) => {
        e.preventDefault();

        if (passwordData.newPassword !== passwordData.confirmPassword) {
            toast.error("New passwords don't match");
            return;
        }

        if (passwordData.newPassword.length < 6) {
            toast.error("Password must be at least 6 characters");
            return;
        }

        setChangingPassword(true);
        try {
            const res = await fetch("/api/user/password", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    currentPassword: passwordData.currentPassword,
                    newPassword: passwordData.newPassword,
                }),
            });

            if (!res.ok) {
                const error = await res.json();
                throw new Error(error.error || "Failed to change password");
            }

            toast.success("Password changed successfully");
            setPasswordData({
                currentPassword: "",
                newPassword: "",
                confirmPassword: "",
            });
            setDialogOpen(false);
        } catch (error: any) {
            console.error("Error changing password:", error);
            toast.error(error.message || "Failed to change password");
        } finally {
            setChangingPassword(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <div className="text-center">
                    <div className="w-16 h-16 border-4 border-[#FF5F00] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
                    <p className="text-gray-600">Loading profile...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-3xl font-bold text-gray-900">Profile Settings</h1>
                <p className="text-gray-600 mt-1">
                    Manage your account information
                </p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Profile Picture */}
                <Card>
                    <CardContent className="pt-6">
                        <div className="text-center">
                            <div className="w-24 h-24 bg-[#FF5F00] rounded-full flex items-center justify-center text-white text-3xl font-bold mx-auto mb-4">
                                {profile?.name?.[0]?.toUpperCase() || "U"}
                            </div>
                            <h3 className="font-semibold text-gray-900">{profile?.name}</h3>
                            <p className="text-sm text-gray-600 mt-1">{profile?.email}</p>
                        </div>
                    </CardContent>
                </Card>

                {/* Profile Form */}
                <Card className="lg:col-span-2">
                    <CardHeader>
                        <CardTitle>Personal Information</CardTitle>
                    </CardHeader>
                    <CardContent>
                        <form onSubmit={handleSaveProfile} className="space-y-4">
                            <div>
                                <Label htmlFor="name">Full Name</Label>
                                <div className="relative mt-1">
                                    <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                                    <Input
                                        id="name"
                                        value={formData.name}
                                        onChange={(e) =>
                                            setFormData({ ...formData, name: e.target.value })
                                        }
                                        className="pl-10"
                                        required
                                    />
                                </div>
                            </div>

                            <div>
                                <Label htmlFor="email">Email Address</Label>
                                <div className="relative mt-1">
                                    <Mail className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                                    <Input
                                        id="email"
                                        type="email"
                                        value={profile?.email || ""}
                                        className="pl-10 bg-gray-50"
                                        disabled
                                    />
                                </div>
                                <p className="text-xs text-gray-500 mt-1">
                                    Email cannot be changed
                                </p>
                            </div>

                            <div>
                                <Label htmlFor="phone">Phone Number</Label>
                                <div className="relative mt-1">
                                    <Phone className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                                    <Input
                                        id="phone"
                                        type="tel"
                                        value={formData.phone}
                                        onChange={(e) =>
                                            setFormData({ ...formData, phone: e.target.value })
                                        }
                                        className="pl-10"
                                        placeholder="+1 234 567 8900"
                                    />
                                </div>
                            </div>

                            <Button type="submit" disabled={saving}>
                                <Save className="w-4 h-4 mr-2" />
                                {saving ? "Saving..." : "Save Changes"}
                            </Button>
                        </form>
                    </CardContent>
                </Card>
            </div>

            {/* Security Section */}
            <Card>
                <CardHeader>
                    <CardTitle>Security</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="flex items-center justify-between">
                        <div>
                            <h4 className="font-medium text-gray-900">Password</h4>
                            <p className="text-sm text-gray-600">
                                Change your account password
                            </p>
                        </div>
                        <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
                            <DialogTrigger asChild>
                                <Button variant="outline">
                                    <Lock className="w-4 h-4 mr-2" />
                                    Change Password
                                </Button>
                            </DialogTrigger>
                            <DialogContent>
                                <DialogHeader>
                                    <DialogTitle>Change Password</DialogTitle>
                                    <DialogDescription>
                                        Enter your current password and choose a new one
                                    </DialogDescription>
                                </DialogHeader>
                                <form onSubmit={handleChangePassword} className="space-y-4">
                                    <div>
                                        <Label htmlFor="currentPassword">Current Password</Label>
                                        <Input
                                            id="currentPassword"
                                            type="password"
                                            value={passwordData.currentPassword}
                                            onChange={(e) =>
                                                setPasswordData({
                                                    ...passwordData,
                                                    currentPassword: e.target.value,
                                                })
                                            }
                                            required
                                        />
                                    </div>
                                    <div>
                                        <Label htmlFor="newPassword">New Password</Label>
                                        <Input
                                            id="newPassword"
                                            type="password"
                                            value={passwordData.newPassword}
                                            onChange={(e) =>
                                                setPasswordData({
                                                    ...passwordData,
                                                    newPassword: e.target.value,
                                                })
                                            }
                                            required
                                        />
                                    </div>
                                    <div>
                                        <Label htmlFor="confirmPassword">Confirm New Password</Label>
                                        <Input
                                            id="confirmPassword"
                                            type="password"
                                            value={passwordData.confirmPassword}
                                            onChange={(e) =>
                                                setPasswordData({
                                                    ...passwordData,
                                                    confirmPassword: e.target.value,
                                                })
                                            }
                                            required
                                        />
                                    </div>
                                    <Button type="submit" disabled={changingPassword} className="w-full">
                                        {changingPassword ? "Changing..." : "Change Password"}
                                    </Button>
                                </form>
                            </DialogContent>
                        </Dialog>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useMemo, useEffect } from "react";
import { useSearchParams, useRouter, usePathname } from "next/navigation";
import { ActivityCard } from "@/components/shared/ActivityCard";
import { FilterSidebar } from "@/components/experiences/FilterSidebar";
import { Activity } from "@/lib/types";

interface ExperiencesClientProps {
    initialActivities: Activity[];
}

export default function ExperiencesClient({ initialActivities }: ExperiencesClientProps) {
    const router = useRouter();
    const pathname = usePathname();
    const searchParams = useSearchParams();

    // Initialize state from URL or defaults
    const [searchQuery, setSearchQuery] = useState(searchParams.get("q") || "");
    const [selectedCategory, setSelectedCategory] = useState(searchParams.get("category") || "All");

    const initialMinPrice = searchParams.get("minPrice") ? Number(searchParams.get("minPrice")) : 0;
    const initialMaxPrice = searchParams.get("maxPrice") ? Number(searchParams.get("maxPrice")) : 600;
    const [priceRange, setPriceRange] = useState([initialMinPrice, initialMaxPrice]);

    const [selectedDuration, setSelectedDuration] = useState(searchParams.get("duration") || "all");

    const initialFeatures = searchParams.get("features") ? searchParams.get("features")?.split(",") || [] : [];
    const [selectedFeatures, setSelectedFeatures] = useState<string[]>(initialFeatures);

    // Sync state with URL params (for external navigation like footer links)
    useEffect(() => {
        const categoryParam = searchParams.get("category");
        if (categoryParam && categoryParam !== selectedCategory) {
            // eslint-disable-next-line react-hooks/exhaustive-deps
            setSelectedCategory(categoryParam);
        }
    }, [searchParams]);

    // Update URL when filters change
    useEffect(() => {
        const params = new URLSearchParams();

        if (searchQuery) params.set("q", searchQuery);
        if (selectedCategory && selectedCategory !== "All") params.set("category", selectedCategory);
        if (priceRange[0] > 0) params.set("minPrice", priceRange[0].toString());
        if (priceRange[1] < 600) params.set("maxPrice", priceRange[1].toString());
        if (selectedDuration && selectedDuration !== "all") params.set("duration", selectedDuration);
        if (selectedFeatures.length > 0) params.set("features", selectedFeatures.join(","));

        const queryString = params.toString();
        const newUrl = queryString ? `${pathname}?${queryString}` : pathname;

        router.replace(newUrl, { scroll: false });
    }, [searchQuery, selectedCategory, priceRange, selectedDuration, selectedFeatures, pathname, router]);

    const filteredActivities = useMemo(() => {
        return initialActivities.filter((activity) => {
            // Search Filter
            if (searchQuery && !activity.title.toLowerCase().includes(searchQuery.toLowerCase()) && !activity.description.toLowerCase().includes(searchQuery.toLowerCase())) {
                return false;
            }

            // Category Filter
            if (selectedCategory !== "All") {
                const matchesCategory = activity.category === selectedCategory;
                const matchesTag = activity.tags?.includes(selectedCategory);

                if (!matchesCategory && !matchesTag) {
                    return false;
                }
            }

            // Price Filter
            if (activity.price < priceRange[0] || activity.price > priceRange[1]) {
                return false;
            }

            // Duration Filter
            if (selectedDuration !== "all") {
                const durationHours = parseInt(activity.duration);
                if (selectedDuration === "half-day" && durationHours > 4) return false;
                if (selectedDuration === "full-day" && durationHours <= 4) return false;
            }

            // Features Filter
            if (selectedFeatures.length > 0) {
                const hasAllFeatures = selectedFeatures.every((feature) =>
                    activity.features?.includes(feature)
                );
                if (!hasAllFeatures) return false;
            }

            return true;
        });
    }, [initialActivities, searchQuery, selectedCategory, priceRange, selectedDuration, selectedFeatures]);

    return (
        <div className="min-h-screen bg-background pt-24 sm:pt-28 pb-12 sm:pb-20">
            <div className="container mx-auto px-4 sm:px-6 lg:px-8 max-w-7xl">
                {/* Page Header */}
                <div className="mb-8 sm:mb-12">
                    <h1 className="text-3xl sm:text-4xl md:text-5xl font-bold text-foreground mb-3 sm:mb-4 tracking-tight">
                        All Things to do
                    </h1>
                    <p className="text-base sm:text-lg text-muted-foreground max-w-2xl mb-6">
                        Discover the magic of Marrakech with our curated selection of premium activities, tours, and adventures.
                    </p>

                    {/* Search Bar */}
                    <div className="relative max-w-md">
                        <input
                            type="text"
                            placeholder="Search things to do..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full px-4 py-3 pl-10 rounded-full border border-border bg-card text-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 shadow-sm"
                        />
                        <svg
                            xmlns="http://www.w3.org/2000/svg"
                            className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground"
                            fill="none"
                            viewBox="0 0 24 24"
                            stroke="currentColor"
                        >
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth={2}
                                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
                            />
                        </svg>
                    </div>
                </div>

                <div className="flex flex-col lg:flex-row gap-6 lg:gap-8">
                    {/* Sidebar - Sticky on desktop */}
                    <aside className="w-full lg:w-1/4 lg:sticky lg:top-24 lg:self-start">
                        <FilterSidebar
                            selectedCategory={selectedCategory}
                            setSelectedCategory={setSelectedCategory}
                            priceRange={priceRange}
                            setPriceRange={setPriceRange}
                            selectedDuration={selectedDuration}
                            setSelectedDuration={setSelectedDuration}
                            selectedFeatures={selectedFeatures}
                            setSelectedFeatures={setSelectedFeatures}
                        />
                    </aside>

                    {/* Main Content - Grid */}
                    <main className="w-full lg:w-3/4">
                        {filteredActivities.length > 0 ? (
                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-6 sm:gap-8">
                                {filteredActivities.filter(activity => activity.id).map((activity) => (
                                    <ActivityCard key={activity.id} activity={activity} />
                                ))}
                            </div>
                        ) : (
                            <div className="flex flex-col items-center justify-center py-12 sm:py-20 text-center bg-secondary/30 rounded-2xl border border-dashed border-border px-4">
                                <h3 className="text-lg sm:text-xl font-semibold text-foreground mb-2">
                                    No Things to do Found
                                </h3>
                                <p className="text-sm sm:text-base text-muted-foreground mb-4">
                                    Try adjusting your search or filters to find what you&apos;re looking for.
                                </p>
                                <button
                                    onClick={() => {
                                        setSearchQuery("");
                                        setSelectedCategory("All");
                                        setPriceRange([0, 6000]);
                                        setSelectedDuration("all");
                                        setSelectedFeatures([]);
                                    }}
                                    className="mt-2 text-primary font-medium hover:underline text-sm sm:text-base"
                                >
                                    Clear all filters
                                </button>
                            </div>
                        )}
                    </main>
                </div>
            </div>
        </div>
    );
}

