export default function LoginPage() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const callbackUrl = searchParams.get('callbackUrl') || '/client';
    const [isLoading, setIsLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);

    // Form state
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            const result = await signIn('credentials', {
                redirect: false,
                email,
                password,
            });

            if (result?.error) {
                toast.error('Invalid email or password');
                return;
            }

            toast.success('Welcome back!');

            // Wait a moment for session to update, then check role
            await new Promise(resolve => setTimeout(resolve, 100));
            router.refresh();

            // Fetch session to check role
            const sessionRes = await fetch('/api/auth/me');
            const sessionData = await sessionRes.json();

            // Redirect based on role
            if (sessionData?.user?.role === 'ADMIN') {
                router.push('/admin/dashboard');
            } else {
                // Only redirect to client if callbackUrl is /client or default
                const finalUrl = callbackUrl.startsWith('/client') ? callbackUrl : '/client';
                router.push(finalUrl);
