/**
 * Base Repository Interface
 * Defines common CRUD operations for all repositories
 */

import { Prisma } from '@prisma/client';

export interface BaseRepository<T, TCreateInput, TUpdateInput, TWhereInput> {
    create(data: TCreateInput): Promise<T>;
    findById(id: string): Promise<T | null>;
    findMany(options?: FindManyOptions<TWhereInput>): Promise<T[]>;
    update(id: string, data: TUpdateInput): Promise<T>;
    delete(id: string): Promise<void>;
    count(where?: TWhereInput): Promise<number>;
}

export interface FindManyOptions<TWhereInput> {
    where?: TWhereInput;
    skip?: number;
    take?: number;
    orderBy?: any;
    include?: any;
    select?: any;
}

export interface PaginationOptions {
    page: number;
    limit: number;
    sortBy?: string;
    sortOrder?: 'asc' | 'desc';
}

/**
 * Booking Repository
 * Handles all database operations for bookings
 */

import prisma from '@/lib/prisma';
import { Booking, Prisma } from '@prisma/client';
import { BaseRepository, FindManyOptions } from './base.repository';

export class BookingRepository implements BaseRepository<
    Booking,
    Prisma.BookingUncheckedCreateInput,
    Prisma.BookingUpdateInput,
    Prisma.BookingWhereInput
> {
    /**
     * Create a new booking
     */
    async create(data: Prisma.BookingUncheckedCreateInput): Promise<Booking> {
        return await prisma.booking.create({ data });
    }

    /**
     * Find booking by ID
     */
    async findById(id: string): Promise<Booking | null> {
        return await prisma.booking.findUnique({
            where: { id },
            include: {
                user: {
                    select: {
                        id: true,
                        name: true,
                        email: true,
                    }
                },
                payments: true,
                review: true,
                service: true,
            }
        });
    }

    /**
     * Find many bookings with options
     */
    async findMany(options?: FindManyOptions<Prisma.BookingWhereInput>): Promise<Booking[]> {
        const query: any = {
            where: options?.where,
            skip: options?.skip,
            take: options?.take,
            orderBy: options?.orderBy,
        };

        // Add either include or select, but not both
        if (options?.include) {
            query.include = options.include;
        } else if (options?.select) {
            query.select = options.select;
        }

        return await prisma.booking.findMany(query);
    }

    /**
     * Find bookings by user ID
     */
    async findByUserId(userId: string): Promise<Booking[]> {
        return await prisma.booking.findMany({
            where: { userId },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Find bookings by email
     */
    async findByEmail(email: string): Promise<Booking[]> {
        return await prisma.booking.findMany({
            where: { email },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Find bookings by user ID or email
     */
    async findByUserIdOrEmail(userId: string, email?: string): Promise<Booking[]> {
        return await prisma.booking.findMany({
            where: {
                OR: [
                    { userId },
                    ...(email ? [{ email }] : [])
                ]
            },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Find bookings by activity ID
     */
    async findByActivityId(activityId: string): Promise<Booking[]> {
        return await prisma.booking.findMany({
            where: { activityId },
            orderBy: { date: 'asc' }
        });
    }

    /**
     * Find bookings by status
     */
    async findByStatus(status: string): Promise<Booking[]> {
        return await prisma.booking.findMany({
            where: { status: status as any },
            orderBy: { createdAt: 'desc' }
        });
    }

    /**
     * Find upcoming bookings
     */
    async findUpcoming(userId?: string): Promise<Booking[]> {
        const now = new Date();
        return await prisma.booking.findMany({
            where: {
                date: { gt: now },
                status: { in: ['PENDING', 'CONFIRMED'] as any },
                ...(userId && { userId })
            },
            orderBy: { date: 'asc' }
        });
    }

    /**
     * Find past bookings
     */
    async findPast(userId?: string): Promise<Booking[]> {
        const now = new Date();
        return await prisma.booking.findMany({
            where: {
                date: { lt: now },
                ...(userId && { userId })
            },
            orderBy: { date: 'desc' }
        });
    }

    /**
     * Update booking
     */
    async update(id: string, data: Prisma.BookingUpdateInput): Promise<Booking> {
        return await prisma.booking.update({
            where: { id },
            data
        });
    }

    /**
     * Update booking status
     */
    async updateStatus(id: string, status: string): Promise<Booking> {
        return await prisma.booking.update({
            where: { id },
            data: { status: status as any }
        });
    }

    /**
     * Delete booking
     */
    async delete(id: string): Promise<void> {
        await prisma.booking.delete({
            where: { id }
        });
    }

    /**
     * Count bookings
     */
    async count(where?: Prisma.BookingWhereInput): Promise<number> {
        return await prisma.booking.count({ where });
    }

    /**
     * Count bookings by status
     */
    async countByStatus(status: string, userId?: string): Promise<number> {
        return await prisma.booking.count({
            where: {
                status: status as any,
                ...(userId && { userId })
            }
        });
    }

    /**
     * Get total revenue
     */
    async getTotalRevenue(where?: Prisma.BookingWhereInput): Promise<number> {
        const result = await prisma.booking.aggregate({
            where,
            _sum: {
                totalPrice: true
            }
        });
        return result._sum.totalPrice || 0;
    }

    /**
     * Get bookings created today
     */
    async findCreatedToday(): Promise<Booking[]> {
        const today = new Date();
