/**
 * Email Service
 * Handles sending emails for bookings, confirmations, and notifications
 * Uses Resend for email delivery
 */

import { Resend } from 'resend';

interface EmailOptions {
    to: string;
    subject: string;
    html: string;
    text?: string;
}

export class EmailService {
    private resend: Resend | null = null;
    private fromEmail: string;

    constructor() {
        // In Next.js, environment variables need to be accessed at runtime, not in constructor
        // We'll initialize Resend lazily when sending emails
        this.fromEmail = process.env.RESEND_FROM_EMAIL || 'Marrakech Tours <onboarding@resend.dev>';
    }

    /**
     * Get or initialize Resend client
     */
    private getResend(): Resend | null {
        if (this.resend) {
            return this.resend;
        }

        const apiKey = process.env.RESEND_API_KEY;
        if (!apiKey) {
            console.warn('ΓÜá∩╕Å RESEND_API_KEY not found in environment variables. Emails will be logged to console only.');
            console.warn('ΓÜá∩╕Å Make sure RESEND_API_KEY is set in .env.local and restart the server.');
            return null;
        }

        try {
            this.resend = new Resend(apiKey);
            console.log('Γ£à Resend email service initialized successfully');
            return this.resend;
        } catch (error) {
            console.error('Γ¥î Failed to initialize Resend:', error);
            return null;
        }
    }

    /**
     * Send an email using Resend
     */
    private async sendEmail(options: EmailOptions): Promise<void> {
        const resend = this.getResend();
        
        if (!resend) {
            // Fallback: log to console if Resend is not configured
            console.log('≡ƒôº Email would be sent (Resend not configured):', {
                to: options.to,
                subject: options.subject,
            });
            return;
        }

        try {
            console.log('≡ƒôº Attempting to send email via Resend:', {
                to: options.to,
                subject: options.subject,
                from: this.fromEmail
            });

            const result = await resend.emails.send({
                from: this.fromEmail,
                to: options.to,
                subject: options.subject,
                html: options.html,
                text: options.text || options.html.replace(/<[^>]*>/g, ''), // Strip HTML for text version
            });

            console.log('≡ƒôº Resend API response:', {
                hasError: !!result.error,
                hasData: !!result.data,
                error: result.error,
                data: result.data
            });

            if (result.error) {
                console.error('Γ¥î Resend API error:', {
                    error: result.error,
                    message: result.error.message,
                    name: result.error.name
                });
                throw new Error(`Email sending failed: ${result.error.message}`);
            }

            if (!result.data || !result.data.id) {
                console.error('Γ¥î Resend API returned no email ID:', result);
                throw new Error('Email sending failed: No email ID returned from Resend');
            }

            console.log('Γ£à Email sent successfully via Resend:', {
                to: options.to,
                subject: options.subject,
                emailId: result.data.id,
                from: this.fromEmail
            });
        } catch (error: any) {
            console.error('Γ¥î Error sending email:', {
                error: error,
                message: error?.message,
                stack: error?.stack,
                to: options.to,
                subject: options.subject
            });
            // Re-throw the error so callers can handle it appropriately
            throw error;
        }
    }

